def parse_block(text,label):
 m=re.search(label+r' \((\d+)x(\d+)\):\n',text)
 if not m: raise ValueError(label)
 h,w=map(int,m.group(1,2)); chunk=text[m.end():].splitlines()[:h]
 rows=[[int(v) for v in ln.split()] for ln in chunk]
 assert len(rows)==h and all(len(row)==w for row in rows),(h,w,[len(x) for x in rows])
 return rows
